import { useNavigate, useParams } from 'react-router-dom';
import { useState, useRef, useEffect } from 'react';
import { fetchCategories, fetchConditions, fetchProduct, updateProduct, deleteProduct, uploadProductImage, type Category, type Condition, type Product } from '../lib/api';

const formatNumber = (num: number | string): string => {
  const n = typeof num === 'string' ? num : String(num);
  return n.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};

export default function AdminEditProductPage() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [product, setProduct] = useState<Product | null>(null);
  const [name, setName] = useState('');
  const [selectedCategoryId, setSelectedCategoryId] = useState('');
  const [selectedConditionId, setSelectedConditionId] = useState('');
  const [description, setDescription] = useState('');
  const [priceRaw, setPriceRaw] = useState('');
  const [stock, setStock] = useState(0);
  const [sku, setSku] = useState('');
  const [visible, setVisible] = useState(true);

  const [categories, setCategories] = useState<Category[]>([]);
  const [conditions, setConditions] = useState<Condition[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const thumbnailInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    Promise.all([
      fetchCategories(),
      fetchConditions(),
      id ? fetchProduct(id) : Promise.resolve(null),
    ]).then(([catRes, condRes, prod]) => {
      setCategories(catRes.data || []);
      setConditions(condRes.data || []);
      if (prod) {
        setProduct(prod);
        setName(prod.name);
        setDescription(prod.description);
        setPriceRaw(String(prod.price));
        setStock(prod.stock);
        setSku(prod.sku);
        setVisible(prod.is_published);
        setSelectedConditionId(prod.condition_id);
        setSelectedCategoryId(prod.categories?.[0]?.id || '');
      }
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [id]);

  const handleSave = async () => {
    if (!id) return;
    setSaving(true);
    try {
      await updateProduct(id, {
        name,
        description,
        condition_id: selectedConditionId,
        sku,
        price: parseInt(priceRaw) || 0,
        stock,
        is_published: visible,
        category_ids: selectedCategoryId ? [selectedCategoryId] : [],
      });
      navigate('/admin/products');
    } catch (err: unknown) {
      alert(`Gagal menyimpan: ${err instanceof Error ? err.message : 'Unknown error'}`);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!id) return;
    if (confirm('Apakah Anda yakin ingin menghapus produk ini?')) {
      try {
        await deleteProduct(id);
        navigate('/admin/products');
      } catch (err: unknown) {
        alert(`Gagal menghapus: ${err instanceof Error ? err.message : 'Unknown error'}`);
      }
    }
  };

  const handleImageUpload = async (file: File) => {
    if (!id) return;
    try {
      await uploadProductImage(id, file);
      const updated = await fetchProduct(id);
      setProduct(updated);
    } catch (err: unknown) {
      alert(`Upload gagal: ${err instanceof Error ? err.message : 'Unknown error'}`);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[50vh]">
        <div className="text-on-surface-variant animate-pulse">Loading...</div>
      </div>
    );
  }

  const mainImage = product?.images?.find(i => i.is_primary) || product?.images?.[0];
  const detailImages = product?.images?.filter(i => !i.is_primary) || [];

  return (
    <main className="p-4 sm:p-8 lg:p-12 animate-in fade-in duration-500 font-body">
      <div className="fixed top-[-10%] right-[-5%] w-[400px] h-[400px] bg-secondary/10 rounded-full blur-[120px] pointer-events-none -z-10"></div>
      <div className="fixed bottom-[-10%] left-[-5%] w-[400px] h-[400px] bg-primary/5 rounded-full blur-[120px] pointer-events-none -z-10"></div>

      <header className="mb-12">
        <h2 className="text-3xl md:text-4xl font-extrabold font-headline tracking-tight text-on-surface">Edit Produk</h2>
        <p className="text-on-surface-variant mt-2 text-sm md:text-base">Perbarui informasi aset kartu di dalam inventaris Anda.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-10">
        {/* Left Column: Visuals */}
        <div className="lg:col-span-5 space-y-6">
          <div className="text-primary font-bold tracking-widest uppercase text-xs mb-2">Pratinjau Aset</div>
          <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
            <div className="aspect-[3/4] overflow-hidden bg-surface-container-low border border-outline-variant/15" style={{ borderRadius: '0.75rem', background: 'rgba(34, 37, 50, 0.6)' }}>
              {mainImage ? (
                <img alt={name} className="w-full h-full object-cover" src={mainImage.url} />
              ) : (
                <div className="w-full h-full flex items-center justify-center">
                  <span className="material-symbols-outlined text-6xl text-on-surface-variant/20">image</span>
                </div>
              )}
            </div>
            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none" style={{ borderRadius: '0.75rem' }}>
              <div className="bg-primary text-on-primary-container px-4 py-2 rounded-lg font-bold flex items-center gap-2 text-sm">
                <span className="material-symbols-outlined">cloud_upload</span>
                {mainImage ? 'Ganti Foto' : 'Upload Foto'}
              </div>
            </div>
            <input ref={fileInputRef} type="file" accept="image/jpeg,image/png,image/webp" className="hidden" onChange={(e) => { const file = e.target.files?.[0]; if (file) handleImageUpload(file); }} />
          </div>

          <div className="grid grid-cols-3 gap-3">
            {detailImages.map((img, i) => (
              <div key={img.id} className={`aspect-square overflow-hidden bg-surface-container-low flex items-center justify-center relative border ${i === 0 ? 'border-primary/20' : 'border-outline-variant/10'}`} style={{ borderRadius: '0.5rem' }}>
                <img alt={`Detail ${i + 1}`} className="w-full h-full object-cover" src={img.url} />
              </div>
            ))}
            <button type="button" onClick={() => thumbnailInputRef.current?.click()} className="aspect-square bg-surface-container-high border border-dashed border-outline-variant flex flex-col items-center justify-center gap-1 hover:bg-surface-bright hover:border-primary/50 transition-colors" style={{ borderRadius: '0.5rem' }}>
              <span className="material-symbols-outlined text-outline">add</span>
              <span className="text-[10px] text-outline uppercase font-bold">Tambah</span>
            </button>
            <input ref={thumbnailInputRef} type="file" accept="image/jpeg,image/png,image/webp" className="hidden" onChange={(e) => { const file = e.target.files?.[0]; if (file) handleImageUpload(file); }} />
          </div>
        </div>

        {/* Right Column: Form Fields */}
        <div className="lg:col-span-7 space-y-8">
          <section className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
              <h2 className="text-2xl font-bold tracking-tight text-on-surface font-headline">Detail Produk</h2>
              <div className="flex items-center gap-3 bg-surface-container-low px-4 py-2 rounded-full">
                <span className="text-[10px] font-bold uppercase tracking-wider text-on-surface-variant">Tampilkan di Katalog</span>
                <button type="button" onClick={() => setVisible(!visible)} className={`w-10 h-5 rounded-full relative flex items-center px-1 transition-colors ${visible ? 'bg-primary/40' : 'bg-surface-container-high'}`}>
                  <div className={`w-3.5 h-3.5 rounded-full shadow-lg absolute transition-all ${visible ? 'bg-primary right-1' : 'bg-outline left-1'}`}></div>
                </button>
              </div>
            </div>

            <div className="space-y-4 text-sm">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-primary tracking-widest uppercase">Nama Produk</label>
                <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-surface-container-low border-none rounded-lg p-4 text-on-surface focus:ring-1 focus:ring-primary focus:bg-surface-container transition-all" />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-on-surface-variant tracking-widest uppercase">Kategori</label>
                  <div className="relative">
                    <select value={selectedCategoryId} onChange={(e) => setSelectedCategoryId(e.target.value)} className="w-full bg-surface-container-low border-none rounded-lg p-4 text-on-surface appearance-none focus:ring-1 focus:ring-primary cursor-pointer">
                      {categories.map(cat => (<option key={cat.id} value={cat.id}>{cat.name}</option>))}
                    </select>
                    <span className="material-symbols-outlined absolute right-4 top-4 pointer-events-none text-outline">expand_more</span>
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-on-surface-variant tracking-widest uppercase">Kondisi</label>
                  <div className="relative">
                    <select value={selectedConditionId} onChange={(e) => setSelectedConditionId(e.target.value)} className="w-full bg-surface-container-low border-none rounded-lg p-4 text-on-surface appearance-none focus:ring-1 focus:ring-primary cursor-pointer">
                      {conditions.map(cond => (<option key={cond.id} value={cond.id}>{cond.name} ({cond.abbreviation})</option>))}
                    </select>
                    <span className="material-symbols-outlined absolute right-4 top-4 pointer-events-none text-outline">expand_more</span>
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-bold text-on-surface-variant tracking-widest uppercase">Deskripsi</label>
                <textarea rows={4} value={description} onChange={(e) => setDescription(e.target.value)} className="w-full bg-surface-container-low border-none rounded-lg p-4 text-on-surface focus:ring-1 focus:ring-primary transition-all resize-none"></textarea>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-primary tracking-widest uppercase">Harga (IDR)</label>
                  <div className="relative">
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-primary font-bold">Rp</span>
                    <input type="text" inputMode="numeric" value={priceRaw ? formatNumber(priceRaw) : ''} onChange={(e) => { const raw = e.target.value.replace(/[^0-9]/g, ''); setPriceRaw(raw === '' ? '' : String(parseInt(raw))); }} className="w-full bg-surface-container-low border-none rounded-lg p-4 pl-12 text-primary font-black text-lg focus:ring-1 focus:ring-primary" />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-on-surface-variant tracking-widest uppercase">Stok Unit</label>
                  <div className="flex items-stretch bg-surface-container-low overflow-hidden" style={{ borderRadius: '0.5rem' }}>
                    <button type="button" onClick={() => setStock(Math.max(0, stock - 1))} className="w-12 min-h-[56px] flex items-center justify-center hover:bg-surface-bright text-outline transition-colors shrink-0">
                      <span className="material-symbols-outlined text-xl">remove</span>
                    </button>
                    <input type="text" inputMode="numeric" value={formatNumber(stock)} onChange={(e) => { const raw = e.target.value.replace(/\./g, ''); setStock(Math.max(0, parseInt(raw) || 0)); }} className="flex-1 bg-transparent border-none text-center font-bold text-on-surface focus:ring-0 min-w-0" />
                    <button type="button" onClick={() => setStock(stock + 1)} className="w-12 min-h-[56px] flex items-center justify-center hover:bg-surface-bright text-primary transition-colors shrink-0">
                      <span className="material-symbols-outlined text-xl">add</span>
                    </button>
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-bold text-on-surface-variant tracking-widest uppercase">SKU / Serial Number</label>
                <input type="text" value={sku} onChange={(e) => setSku(e.target.value)} className="w-full bg-surface-container-low border-none rounded-lg p-4 text-on-surface-variant font-mono focus:ring-1 focus:ring-primary" />
              </div>
            </div>
          </section>

          <div className="flex flex-col gap-4 pt-6">
            <div className="flex flex-col sm:flex-row gap-4">
              <button onClick={handleSave} disabled={saving} className="flex-1 bg-gradient-to-r from-primary to-primary-container text-on-primary-container font-black py-4 shadow-lg shadow-primary/10 active:scale-[0.98] transition-all flex items-center justify-center gap-2 text-sm disabled:opacity-50" style={{ borderRadius: '0.75rem' }}>
                <span className="material-symbols-outlined">{saving ? 'hourglass_empty' : 'save'}</span>
                {saving ? 'Menyimpan...' : 'Simpan Perubahan'}
              </button>
              <button onClick={() => navigate('/admin/products')} className="px-8 border border-primary/30 text-primary font-bold py-4 hover:bg-primary/10 transition-all active:scale-[0.98]" style={{ borderRadius: '0.75rem' }}>
                Batal
              </button>
            </div>
            <div className="pt-10 border-t border-outline-variant/15">
              <button onClick={handleDelete} className="w-full py-4 text-error font-bold border border-error/20 hover:bg-error-container/10 transition-all flex items-center justify-center gap-2 active:scale-[0.98]" style={{ borderRadius: '0.75rem' }}>
                <span className="material-symbols-outlined">delete</span>
                Hapus Produk dari Inventaris
              </button>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
